[CmdletBinding()]
param(
 [string]$RepositoryRoot,
 [string]$ReaderDirectory,
 [string]$FixturePath,
 [Parameter(Mandatory=$true)][string]$OutputDirectory
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
# Run-scoped synthetic archives only. Existing output directories are preserved.
if(-not$RepositoryRoot){$RepositoryRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))}
if(-not$ReaderDirectory){$ReaderDirectory=Join-Path $RepositoryRoot 'scripts/runtime'}
if(-not$FixturePath){$FixturePath=Join-Path $RepositoryRoot 'tests/Chunk7Diagnostics/OwnedPairsEvidenceFixtures.json'}
if(Test-Path -LiteralPath $OutputDirectory){throw 'Independent refusal tests preserve every previous run.'};[void][IO.Directory]::CreateDirectory($OutputDirectory)
. (Join-Path $ReaderDirectory 'RuntimeHarness.Common.ps1')
. (Join-Path $ReaderDirectory 'Chunk7OwnedPairsFixtures.ps1')
. (Join-Path $ReaderDirectory 'Chunk7OwnedSchema1Fixtures.ps1')
. (Join-Path $ReaderDirectory 'Chunk7LoadRefusalFixtures.ps1')
. (Join-Path $ReaderDirectory 'Chunk7LoadRefusalEvidence.ps1')
Add-Type -AssemblyName System.IO.Compression
function Clone($x){$x|ConvertTo-Json -Depth 90|ConvertFrom-Json}
function Put($x,[string]$n,$v){$x|Add-Member -NotePropertyName $n -NotePropertyValue $v -Force}
$results=[Collections.Generic.List[object]]::new();$clock=[Diagnostics.Stopwatch]::StartNew()
function Check([string]$Name,[scriptblock]$Body,[bool]$Refuse=$false,[string]$Pattern=''){$errorText=$null;$ok=$false;try{&$Body;$ok=-not$Refuse}catch{$errorText=$_.Exception.Message;$ok=$Refuse-and(-not$Pattern-or$errorText-match$Pattern)};$results.Add([pscustomobject]@{name=$Name;pass=$ok;expectedRefusal=$Refuse;error=$errorText});if(-not$ok){Write-Output ('FAIL '+$Name+': '+$errorText)}}
# Only verified ancestor qualification, current lock/process ownership and lab
# location are facades. Actual paths, links, streams, hashes, ticks, ZIP/member
# guards, JSON uniqueness, receipt readers and CREATE_NEW operations are intact.
function Get-KmcLabRoot{$script:rigLabRoot}
function Assert-KmcRuntimeLockOwner($Lock){if($script:blockLock-or$Lock.RunId-cne$script:rigLock.RunId-or$Lock.Token-cne$script:rigLock.Token){throw 'test lock boundary refused'};$Lock}
function Assert-KmcNoGameProcesses{if($script:blockProcess){throw 'test process boundary refused'}}
function Get-KmcChunk7OwnedPairsSource($Selection,$Checkpoint,$Fixture,$Candidate){
 if($script:blockSource-or$Checkpoint-cnotin@('multi-malformed-refusal-manual','multi-future-refusal-manual')-or$Selection.sourceRunId-cne$script:qualifiedSelection.sourceRunId-or$Selection.sourceArtifactSha256-cne$script:qualifiedSelection.sourceArtifactSha256-or$Selection.sourceArchiveSha256-cne$script:qualifiedSelection.sourceArchiveSha256){throw 'verified-source completion boundary refused'}
 Clone $script:qualifiedSource
}
function Write-Zip([string]$Path,$Rows){
 $file=[IO.File]::Open($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$zip=$null
 try{$zip=[IO.Compression.ZipArchive]::new($file,[IO.Compression.ZipArchiveMode]::Create,$false);foreach($row in $Rows){$entry=$zip.CreateEntry([string]$row.name);$inner=$entry.Open();try{$bytes=if($null-ne$row.PSObject.Properties['bytes']-and$row.bytes-is[byte[]]){$row.bytes}else{[Text.UTF8Encoding]::new($false,$true).GetBytes([string]$row.text)};$inner.Write($bytes,0,$bytes.Length)}finally{$inner.Dispose()}}}finally{if($zip){$zip.Dispose()};$file.Dispose()}
}
function Change-ZipMember([string]$Path,[string]$Name,[string]$Text){$f=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$z=$null;try{$z=[IO.Compression.ZipArchive]::new($f,[IO.Compression.ZipArchiveMode]::Update,$false);$e=@($z.Entries|Where-Object FullName -CEQ $Name);foreach($x in $e){$x.Delete()};$e=$z.CreateEntry($Name);$s=$e.Open();try{$b=[Text.Encoding]::UTF8.GetBytes($Text);$s.Write($b,0,$b.Length)}finally{$s.Dispose()}}finally{if($z){$z.Dispose()};$f.Dispose()}}
function New-Rig([string]$Checkpoint='multi-malformed-refusal-manual',$Rows=$null){
 $script:rigLabRoot=Join-Path $OutputDirectory ('lab-'+[Guid]::NewGuid().ToString('N'));$script:blockLock=$false;$script:blockProcess=$false;$script:blockSource=$false
 $base=([IO.File]::ReadAllText($FixturePath)|ConvertFrom-Json).fixtures|Where-Object name -CEQ 'persistence-load-multi-exploration-manual'
 $metadata=Clone $base.artifact.observations.loadedArchive;$metadata.AreaId='b10e86516b6437d45a629931c30936fe'
 $selection=[pscustomobject][ordered]@{case='owner-seed-load-refusal';sourceRunId='accepted-manual';sourceArtifactSha256=('6'*64);sourceArchiveSha256=('5'*64);checkpointSourceRunId='accepted-cold';checkpointSourceArtifactSha256=('8'*64);seedId='KMC_C7_OWNER_SEED';seedSha256=('9'*64);riderAId=$base.request.ownedPairs.riderAId;mountAId=$base.request.ownedPairs.mountAId;riderBId=$base.request.ownedPairs.riderBId;mountBId=$base.request.ownedPairs.mountBId;partyIds=$base.request.ownedPairs.partyIds;baseGameOnly=$true;expectedNativeLoadCount=1;expectedNativeWriteCount=0}
 $dir=Join-Path $script:rigLabRoot 'runtime-staging/persistence-accepted-manual/Saved Games';[void][IO.Directory]::CreateDirectory($dir);$primary=Join-Path $dir 'Manual_303_KMC_C7_SEED_WORLD.zks'
 if($null-eq$Rows){$Rows=@([pscustomobject]@{name='header.json';text='{"Name":"KMC_C7_SEED_WORLD","game":"private synthetic fixture"}'},[pscustomobject]@{name='player.json';text='native player bytes retained verbatim'},[pscustomobject]@{name='areas/field.json';text="native field bytes`nwith exact newline"},[pscustomobject]@{name='kmc-mounted-state';text=($metadata|ConvertTo-Json -Depth 40 -Compress)})}
 Write-Zip $primary $Rows;[IO.File]::SetLastWriteTimeUtc($primary,[DateTime]::new(638960000000000000,[DateTimeKind]::Utc))
 $file=Get-Item -LiteralPath $primary;$selection.sourceArchiveSha256=Get-KmcSha256 $primary
 $descriptor=[pscustomobject][ordered]@{internalName='KMC_C7_SEED_WORLD';fileName=$file.Name;sha256=$selection.sourceArchiveSha256;length=[long]$file.Length;lastWriteTimeUtcTicks=[long]$file.LastWriteTimeUtc.Ticks;gameId=$metadata.CampaignId;gameName='Synthetic Independent Fixture';area=$metadata.AreaId}
 $artifact=Join-Path $script:rigLabRoot 'accepted-world.json';[IO.File]::WriteAllText($artifact,([pscustomobject]@{observations=[pscustomobject]@{nativeWrite=[pscustomobject]@{archive=$metadata}}}|ConvertTo-Json -Depth 50),[Text.UTF8Encoding]::new($false));$selection.sourceArtifactSha256=Get-KmcSha256 $artifact
 $source=[pscustomobject]@{path=$primary;descriptor=$descriptor;artifactPath=$artifact;artifactSha256=$selection.sourceArtifactSha256;artifactLength=[long](Get-Item -LiteralPath $artifact).Length;sourceRunId=$selection.sourceRunId;ownerSeedDerived=$true}
 $lock=[pscustomobject]@{RunId=('independent-'+[Guid]::NewGuid().ToString('N'));Token=('1'*64)};$script:rigLock=Clone $lock;$script:qualifiedSource=Clone $source;$script:qualifiedSelection=Clone $selection
 $candidate=[pscustomobject]@{commit=('2'*40);dllSha256=('3'*64);dllMvid='33333333-3333-4333-8333-333333333333'}
 [pscustomobject]@{selection=$selection;source=$source;fixture=(Clone $base.request.fixture);candidate=$candidate;lock=$lock;checkpoint=$Checkpoint;metadata=$metadata;primary=$primary;lab=$script:rigLabRoot;request=$null;derivative=$null;profile=$null}
}
function Derive($Rig){New-KmcChunk7LoadRefusalInput $Rig.source $Rig.selection $Rig.checkpoint $Rig.fixture $Rig.candidate $Rig.lock}
function Stage-Rig($Rig){
 $Rig.derivative=Derive $Rig;$r=[pscustomobject][ordered]@{scenario='chunk7-owned-two-pair-campaign';runId=$Rig.lock.RunId;transactionToken=$Rig.lock.Token;ownedPairs=(Clone $Rig.selection);persistenceCase=$Rig.checkpoint;persistenceLoad=(Clone $Rig.source.descriptor);persistenceAlternate=(Clone $Rig.derivative.descriptor);loadRefusalDerivationSha256=$Rig.derivative.receiptSha256;fixture=(Clone $Rig.fixture)};$Rig.request=$r
 $Rig.profile=Join-Path $Rig.lab ('runtime-staging/persistence-'+$Rig.lock.RunId);$saves=Join-Path $Rig.profile 'Saved Games';[void][IO.Directory]::CreateDirectory($saves)
 [IO.File]::Copy($Rig.primary,(Join-Path $saves $r.persistenceLoad.fileName),$false);[IO.File]::SetLastWriteTimeUtc((Join-Path $saves $r.persistenceLoad.fileName),[DateTime]::new($r.persistenceLoad.lastWriteTimeUtcTicks,[DateTimeKind]::Utc))
 $r
}
function Copy-Rig($Rig){Copy-KmcChunk7LoadRefusalInputs $Rig.derivative $Rig.profile $Rig.lock $Rig.request}
function Verify-Rig($Rig){Assert-KmcChunk7LoadRefusalInputBytes $Rig.request (Join-Path $Rig.profile 'Saved Games') (Join-Path $Rig.profile 'owner-seed-load-refusal-derivation.json')}
function RePin-Source($Rig){$f=Get-Item -LiteralPath $Rig.primary;$Rig.source.descriptor.sha256=Get-KmcSha256 $Rig.primary;$Rig.source.descriptor.length=[long]$f.Length;$Rig.source.descriptor.lastWriteTimeUtcTicks=[long]$f.LastWriteTimeUtc.Ticks;$Rig.selection.sourceArchiveSha256=$Rig.source.descriptor.sha256;$script:qualifiedSource=Clone $Rig.source;$script:qualifiedSelection=Clone $Rig.selection}
function RePin-StagedAlternate($Rig){$path=Join-Path $Rig.profile ('Saved Games/'+$Rig.request.persistenceAlternate.fileName);$file=Get-Item -LiteralPath $path;$s=[IO.File]::OpenRead($path);try{$members=Get-KmcChunk7LoadRefusalMembers $s}finally{$s.Dispose()};$receiptPath=Join-Path $Rig.profile 'owner-seed-load-refusal-derivation.json';$receipt=[IO.File]::ReadAllText($receiptPath)|ConvertFrom-Json;$Rig.request.persistenceAlternate.sha256=Get-KmcSha256 $path;$Rig.request.persistenceAlternate.length=[long]$file.Length;$Rig.request.persistenceAlternate.lastWriteTimeUtcTicks=[long]$file.LastWriteTimeUtc.Ticks;$receipt.descriptor=Clone $Rig.request.persistenceAlternate;$receipt.members=$members.members;$m=@($receipt.members|Where-Object name -CEQ 'kmc-mounted-state')[0];$receipt.metadataSha256=$m.sha256;$receipt.metadataLength=$m.length;[IO.File]::WriteAllText($receiptPath,($receipt|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));$Rig.request.loadRefusalDerivationSha256=Get-KmcSha256 $receiptPath}
foreach($checkpoint in @('multi-malformed-refusal-manual','multi-future-refusal-manual')){
 Check ('exact metadata-only derivation and locked CREATE_NEW staging '+$checkpoint){$rig=New-Rig $checkpoint;$before=[IO.File]::ReadAllBytes($rig.primary);[void](Stage-Rig $rig);Copy-Rig $rig;Verify-Rig $rig;$receipt=Read-KmcOwnedSchema1PinnedJson $rig.derivative.receiptPath $rig.derivative.receiptSha256 256KB;Assert-KmcChunk7LoadRefusalDerivation $receipt $rig.request;if((Get-KmcSha256 $rig.primary)-cne$rig.source.descriptor.sha256-or(Get-Item -LiteralPath $rig.primary).LastWriteTimeUtc.Ticks-ne$rig.source.descriptor.lastWriteTimeUtcTicks-or$receipt.nativeMembersVerified-ne3-or$rig.request.ownedPairs.expectedNativeLoadCount-ne1-or$rig.request.ownedPairs.expectedNativeWriteCount-ne0){throw 'Native member/source identity or exhausted load quota changed.'};$s=[IO.File]::OpenRead($rig.derivative.path);try{$members=Get-KmcChunk7LoadRefusalMembers $s}finally{$s.Dispose()};if($checkpoint-ceq'multi-malformed-refusal-manual'){if($members.metadataText-cne'{"SchemaVersion":3,'){throw 'Malformed bytes differ.'}}else{Assert-KmcJsonObjectMembersUnique -Json $members.metadataText -Description 'future fixture';$v=$members.metadataText|ConvertFrom-Json;if($v.SchemaVersion-ne99){throw 'Future schema differs.'};$v.SchemaVersion=3;if((ConvertTo-KmcChunk7Canonical $v)-cne(ConvertTo-KmcChunk7Canonical $rig.metadata)){throw 'Future mutation changed another metadata value.'}}}
}
foreach($fault in @('lock','process','source-requalify','source-hash','source-length','source-ticks','source-outside','producer-pin','producer-graph','metadata-schema','metadata-duplicate')){
 Check ('derivation refuses '+$fault){$rig=New-Rig;switch($fault){'lock'{$script:blockLock=$true};'process'{$script:blockProcess=$true};'source-requalify'{$script:blockSource=$true};'source-hash'{$rig.source.descriptor.sha256='e'*64;$script:qualifiedSource=Clone $rig.source};'source-length'{$rig.source.descriptor.length++;$script:qualifiedSource=Clone $rig.source};'source-ticks'{$rig.source.descriptor.lastWriteTimeUtcTicks++;$script:qualifiedSource=Clone $rig.source};'source-outside'{$rig.source.path=Join-Path $rig.lab 'foreign.zks';[IO.File]::Copy($rig.primary,$rig.source.path,$false);$script:qualifiedSource=Clone $rig.source};'producer-pin'{[IO.File]::AppendAllText($rig.source.artifactPath,' ')};'producer-graph'{$v=[IO.File]::ReadAllText($rig.source.artifactPath)|ConvertFrom-Json;$v.observations.nativeWrite.archive.Pairs[1].Generation++;[IO.File]::WriteAllText($rig.source.artifactPath,($v|ConvertTo-Json -Depth 50));$rig.selection.sourceArtifactSha256=Get-KmcSha256 $rig.source.artifactPath;$script:qualifiedSelection=Clone $rig.selection};'metadata-schema'{$v=Clone $rig.metadata;$v.SchemaVersion=2;Change-ZipMember $rig.primary 'kmc-mounted-state' ($v|ConvertTo-Json -Depth 40 -Compress);RePin-Source $rig};'metadata-duplicate'{Change-ZipMember $rig.primary 'kmc-mounted-state' '{"SchemaVersion":3,"SchemaVersion":3}';RePin-Source $rig}};[void](Derive $rig)} $true
}
foreach($memberFault in @('../escape','/absolute','C:drive','dir\entry','dir//entry','dir/./entry','dir/../entry','duplicate','case-collision','missing-header','wrong-header-case','missing-metadata','empty-metadata','oversized-metadata','invalid-utf8')){
 Check ('actual ZIP member guard refuses '+$memberFault){$rows=@([pscustomobject]@{name='header.json';text='native header'},[pscustomobject]@{name='kmc-mounted-state';text='{"SchemaVersion":3}'})
 switch($memberFault){'duplicate'{$rows+=@([pscustomobject]@{name='header.json';text='collision'})};'case-collision'{$rows+=@([pscustomobject]@{name='HEADER.JSON';text='collision'})};'missing-header'{$rows[0].name='other.json'};'wrong-header-case'{$rows[0].name='HEADER.JSON'};'missing-metadata'{$rows[1].name='other-state'};'empty-metadata'{$rows[1].text=''};'oversized-metadata'{$rows[1].text='x'*131073};'invalid-utf8'{$rows[1]=[pscustomobject]@{name='kmc-mounted-state';bytes=[byte[]]@(255,254,255)}};default{$rows+=@([pscustomobject]@{name=$memberFault;text='unsafe'})}};$rig=New-Rig 'multi-malformed-refusal-manual' $rows;$s=[IO.File]::OpenRead($rig.primary);try{[void](Get-KmcChunk7LoadRefusalMembers $s)}finally{$s.Dispose()}} $true
}
foreach($fault in @('wrong-lock','wrong-run','wrong-token','foreign-profile','wrong-descriptor','receipt-pin','alternate-hash','alternate-ticks','alternate-length','receipt-bytes','existing-alternate','existing-receipt')){
 Check ('locked staging refuses '+$fault){$rig=New-Rig;[void](Stage-Rig $rig);switch($fault){'wrong-lock'{$script:blockLock=$true};'wrong-run'{$rig.request.runId='foreign'};'wrong-token'{$rig.request.transactionToken='f'*64};'foreign-profile'{$rig.profile=Join-Path $rig.lab 'runtime-staging/persistence-foreign';[void][IO.Directory]::CreateDirectory((Join-Path $rig.profile 'Saved Games'))};'wrong-descriptor'{$rig.request.persistenceAlternate.gameName='foreign'};'receipt-pin'{$rig.request.loadRefusalDerivationSha256='e'*64};'alternate-hash'{[IO.File]::AppendAllText($rig.derivative.path,'changed')};'alternate-ticks'{[IO.File]::SetLastWriteTimeUtc($rig.derivative.path,([IO.File]::GetLastWriteTimeUtc($rig.derivative.path).AddSeconds(1)))};'alternate-length'{$rig.request.persistenceAlternate.length++;$rig.derivative.descriptor.length++};'receipt-bytes'{[IO.File]::AppendAllText($rig.derivative.receiptPath,' ')};'existing-alternate'{[IO.File]::WriteAllText((Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceAlternate.fileName)),'sentinel')};'existing-receipt'{[IO.File]::WriteAllText((Join-Path $rig.profile 'owner-seed-load-refusal-derivation.json'),'sentinel')}};Copy-Rig $rig} $true
}
Check 'staging cannot overwrite a prior derivative or receipt' {$rig=New-Rig;[void](Stage-Rig $rig);Copy-Rig $rig;$before=Get-KmcSha256 (Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceAlternate.fileName));$refused=$false;try{Copy-Rig $rig}catch{$refused=$true};if(-not$refused-or(Get-KmcSha256 (Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceAlternate.fileName)))-cne$before){throw 'CREATE_NEW overwrote the alternate.'}}
foreach($fault in @('primary-bytes','primary-ticks','alternate-bytes','alternate-ticks','receipt-bytes','wrong-schema-mutation','native-member-changed')){
 Check ('staged byte verifier refuses '+$fault){$rig=New-Rig;[void](Stage-Rig $rig);Copy-Rig $rig;$primary=Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceLoad.fileName);$alt=Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceAlternate.fileName);switch($fault){'primary-bytes'{[IO.File]::AppendAllText($primary,' ')};'primary-ticks'{[IO.File]::SetLastWriteTimeUtc($primary,([IO.File]::GetLastWriteTimeUtc($primary).AddSeconds(1)))};'alternate-bytes'{[IO.File]::AppendAllText($alt,' ')};'alternate-ticks'{[IO.File]::SetLastWriteTimeUtc($alt,([IO.File]::GetLastWriteTimeUtc($alt).AddSeconds(1)))};'receipt-bytes'{[IO.File]::AppendAllText((Join-Path $rig.profile 'owner-seed-load-refusal-derivation.json'),' ')};'wrong-schema-mutation'{Change-ZipMember $alt 'kmc-mounted-state' '{"SchemaVersion":98}'};'native-member-changed'{Change-ZipMember $alt 'player.json' 'mutated native payload'}};Verify-Rig $rig} $true
}
foreach($fault in @('restoration-proof','ordinary-contract','checkpoint','unknown-field','duplicate-member','case-collision','native-member-hash','header-omitted','metadata-unchanged','mutation','counter','source-area','alternate-area')){
 Check ('closed receipt verifier refuses '+$fault){$rig=New-Rig;[void](Stage-Rig $rig);$v=Read-KmcOwnedSchema1PinnedJson $rig.derivative.receiptPath $rig.derivative.receiptSha256 256KB;switch($fault){'restoration-proof'{$v.nativeRestorationProven=$true};'ordinary-contract'{$v.contract='ordinary'};'checkpoint'{$v.checkpoint='multi-exploration-manual'};'unknown-field'{Put $v extra $true};'duplicate-member'{$v.members+=@((Clone $v.members[0]))};'case-collision'{$v.members+=@([pscustomobject]@{name='HEADER.JSON';length=1;sha256=('e'*64)})};'native-member-hash'{$v.members[0].sha256='e'*64};'header-omitted'{$v.members[0].name='other.json'};'metadata-unchanged'{$m=@($v.members|Where-Object name -CEQ 'kmc-mounted-state')[0];$prior=@($v.sourceMembers|Where-Object name -CEQ 'kmc-mounted-state')[0];$m.sha256=$prior.sha256;$v.metadataSha256=$m.sha256};'mutation'{$v.mutation='future-schema-99'};'counter'{$v.nativeMembersVerified++};'source-area'{$v.sourceDescriptor.area='e'*32};'alternate-area'{$v.descriptor.area='e'*32}};Assert-KmcChunk7LoadRefusalDerivation $v $rig.request} $true
}
foreach($fault in @('second-load','write','checkpoint-family','other-case','no-source','alias-role','source-aliased-seed','companion','source-area')){
 Check ('refusal exact selection refuses '+$fault){$rig=New-Rig;$r=[pscustomobject]@{scenario='chunk7-owned-two-pair-campaign';runId=$rig.lock.RunId;ownedPairs=$rig.selection;persistenceCase=$rig.checkpoint};switch($fault){'second-load'{$r.ownedPairs.expectedNativeLoadCount=2};'write'{$r.ownedPairs.expectedNativeWriteCount=1};'checkpoint-family'{$r.persistenceCase='multi-area-autosave'};'other-case'{$r.ownedPairs.case='owner-seed-checkpoint-load'};'no-source'{$r.ownedPairs.sourceRunId=$null};'alias-role'{$r.ownedPairs.mountBId=$r.ownedPairs.mountAId};'source-aliased-seed'{$r.ownedPairs.sourceArchiveSha256=$r.ownedPairs.seedSha256};'companion'{Put $r.ownedPairs companionId $r.ownedPairs.partyIds[0]};'source-area'{Put $r.ownedPairs sourceArea 'b10e86516b6437d45a629931c30936fe'}};Assert-KmcChunk7LoadRefusalSelection $r $r.ownedPairs $r.persistenceCase} $true
}
foreach($fault in @('schema-string','schema2','schema4','null-schema','unknown-checkpoint')){Check ('exact mutation constructor refuses '+$fault){$v=[pscustomobject]@{SchemaVersion=3};$cp='multi-future-refusal-manual';switch($fault){'schema-string'{$v.SchemaVersion='3'};'schema2'{$v.SchemaVersion=2};'schema4'{$v.SchemaVersion=4};'null-schema'{$v.SchemaVersion=$null};'unknown-checkpoint'{$cp='multi-exploration-manual'}};[void](Get-KmcChunk7LoadRefusalMutation $v $cp)} $true}
foreach($fault in @('wrong-future-schema','extra-malformed-byte','native-member')){Check ('actual bytes verifier rejects consistently re-pinned forgery '+$fault){$rig=New-Rig $(if($fault-ceq'wrong-future-schema'){'multi-future-refusal-manual'}else{'multi-malformed-refusal-manual'});[void](Stage-Rig $rig);Copy-Rig $rig;$path=Join-Path $rig.profile ('Saved Games/'+$rig.request.persistenceAlternate.fileName);switch($fault){'wrong-future-schema'{$v=Clone $rig.metadata;$v.SchemaVersion=98;Change-ZipMember $path 'kmc-mounted-state' ($v|ConvertTo-Json -Depth 40 -Compress)};'extra-malformed-byte'{Change-ZipMember $path 'kmc-mounted-state' '{"SchemaVersion":3, '};'native-member'{Change-ZipMember $path 'player.json' 'forged native member'}};RePin-StagedAlternate $rig;Verify-Rig $rig} $true}
Check 'actual source hard-link guard refuses alias' {$rig=New-Rig;$alias=Join-Path (Split-Path $rig.primary -Parent) 'synthetic-hardlink.zks';[void](New-Item -ItemType HardLink -Path $alias -Target $rig.primary);$rig.source.path=$alias;$script:qualifiedSource=Clone $rig.source;[void](Derive $rig)} $true 'hard link'
Check 'actual copied alternate hard-link guard refuses alias' {$rig=New-Rig;[void](Stage-Rig $rig);$alias=Join-Path (Split-Path $rig.derivative.path -Parent) 'synthetic-hardlink.zks';[void](New-Item -ItemType HardLink -Path $alias -Target $rig.derivative.path);$rig.derivative.path=$alias;Copy-Rig $rig} $true 'hard link'
Check 'actual source reparse guard refuses private junction' {$rig=New-Rig;$target=Join-Path $rig.lab 'junction-target';[void][IO.Directory]::CreateDirectory($target);[IO.File]::Copy($rig.primary,(Join-Path $target (Split-Path $rig.primary -Leaf)),$false);$alias=Join-Path (Split-Path $rig.primary -Parent) 'synthetic-junction';[void](New-Item -ItemType Junction -Path $alias -Target $target);$rig.source.path=Join-Path $alias (Split-Path $rig.primary -Leaf);$script:qualifiedSource=Clone $rig.source;[void](Derive $rig)} $true 'reparse point'
$clock.Stop();$passed=@($results|Where-Object pass).Count;$failed=$results.Count-$passed
$inputs=@(foreach($leaf in @('Chunk7LoadRefusalFixtures.ps1','Chunk7LoadRefusalEvidence.ps1','Chunk7OwnedPairsEvidence.ps1','Chunk7OwnedPairsFixtures.ps1','Chunk7OwnedSchema1Fixtures.ps1','RuntimeHarness.Common.ps1')){$p=Join-Path $ReaderDirectory $leaf;[pscustomobject]@{path=$p;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}})
[IO.File]::WriteAllText((Join-Path $OutputDirectory 'receipt.json'),([pscustomobject]@{status=$(if($failed){'FAIL'}else{'PASS'});passed=$passed;failed=$failed;seconds=$clock.Elapsed.TotalSeconds;nativeInvoked=$false;generatedArchivesOnly=$true;facades=@('verified complete source qualification','current private lock ownership','game process absence','private lab root');inputs=$inputs;results=@($results)}|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Write-Output ('Independent refusal copies '+$passed+' PASS / '+$failed+' FAIL');if($failed){exit 1}
